package br.com.finai.service;
import br.com.finai.adapter.ProvedorIa;
import br.com.finai.dto.Contratos.*;
import br.com.finai.model.*;
import br.com.finai.repository.*;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.*;
import java.math.*;
import java.time.*;
import java.util.*;
import static org.mockito.Mockito.*;
import static org.assertj.core.api.Assertions.*;
class InteligenciaServiceTest {
 ProvedorIa provedor=mock(ProvedorIa.class);FinanceiroService financeiro=mock(FinanceiroService.class);CotaIaService cotas=mock(CotaIaService.class);SugestaoLancamentoRepository sugestoes=mock(SugestaoLancamentoRepository.class);CorrecaoCategoriaRepository correcoes=mock(CorrecaoCategoriaRepository.class);ObjectMapper mapper=new ObjectMapper();UUID usuario=UUID.randomUUID();Categoria categoria;InteligenciaService service=new InteligenciaService(provedor,financeiro,cotas,sugestoes,correcoes,mapper);
 @BeforeEach void preparar(){categoria=new Categoria();categoria.nome="Alimentação";categoria.tipo=TipoLancamento.DESPESA;when(financeiro.categorias(usuario)).thenReturn(List.of(categoria));when(correcoes.findTop100ByUsuarioIdOrderByCriadaEmDesc(usuario)).thenReturn(List.of());when(sugestoes.save(any())).thenAnswer(i->i.getArgument(0));}
 JsonNode resposta() throws Exception {return mapper.readTree("{\"campos\":{\"tipo\":\"DESPESA\",\"valor\":38.20,\"data\":\""+RegrasFinanceiras.hoje()+"\",\"categoriaId\":\""+categoria.id+"\",\"descricao\":\"Almoço\",\"estabelecimento\":null,\"formaPagamento\":\"Pix\"},\"confianca\":{\"tipo\":0.99,\"valor\":0.79,\"data\":0.95,\"categoriaId\":0.9,\"descricao\":0.99,\"estabelecimento\":0.1,\"formaPagamento\":0.5}}");}
 @Test void respeitaConfiancaENaoSalvaAntesDeConfirmar() throws Exception {when(provedor.gerar(any(),any(),any(),anyBoolean())).thenReturn(resposta());var s=service.interpretar(usuario,"Paguei 38,20 no almoço");assertThat(s.manual()).isFalse();assertThat(s.conferirValor()).isTrue();assertThat(s.pendentes()).contains("estabelecimento","formaPagamento");assertThat(s.campos().get("formaPagamento")).isNull();verify(financeiro,never()).salvar(any(),any(),any(),any());}
 @Test void falhaTentaNovamenteEOfereceManual(){when(provedor.gerar(any(),any(),any(),anyBoolean())).thenThrow(new IllegalStateException());var s=service.interpretar(usuario,"Almoço 38");assertThat(s.manual()).isTrue();assertThat(s.campos()).containsOnlyKeys("descricao");verify(provedor,times(2)).gerar(any(),any(),any(),anyBoolean());assertThatThrownBy(()->service.interpretar(usuario,"x".repeat(281))).isInstanceOf(RegraNegocioException.class);}
 @Test void rejeitaEsquemaCategoriaValorEConfianca() throws Exception {var r=(com.fasterxml.jackson.databind.node.ObjectNode)resposta();((com.fasterxml.jackson.databind.node.ObjectNode)r.get("campos")).put("categoriaId",UUID.randomUUID().toString());assertThatThrownBy(()->service.validar(r,List.of(categoria))).isInstanceOf(IllegalArgumentException.class);var invalida=(com.fasterxml.jackson.databind.node.ObjectNode)resposta();((com.fasterxml.jackson.databind.node.ObjectNode)invalida.get("confianca")).put("valor",1.2);assertThatThrownBy(()->service.validar(invalida,List.of(categoria))).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->service.validar(mapper.createObjectNode(),List.of(categoria))).isInstanceOf(IllegalArgumentException.class);}
 @Test void confirmaUmaVezERegistraCorrecao() throws Exception {SugestaoLancamento s=new SugestaoLancamento();s.usuarioId=usuario;s.textoOriginal="Paguei 38 no almoço";s.dados=mapper.writeValueAsString(Map.of("categoriaId",categoria.id.toString()));when(sugestoes.obterParaConfirmacao(s.id,usuario)).thenReturn(Optional.of(s));UUID nova=UUID.randomUUID();Lancamento l=new Lancamento();l.categoriaId=nova;when(financeiro.salvar(eq(usuario),isNull(),any(),eq("IA"))).thenReturn(l);var entrada=new LancamentoEntrada(TipoLancamento.DESPESA,new BigDecimal("38"),RegrasFinanceiras.hoje(),nova,"Almoço","","Pix");assertThatThrownBy(()->service.confirmar(usuario,s.id,new Confirmacao(false,entrada))).isInstanceOf(RegraNegocioException.class);service.confirmar(usuario,s.id,new Confirmacao(true,entrada));verify(correcoes).save(any());verify(sugestoes).delete(s);service.descartar(usuario,s.id);s.criadaEm=Instant.now().minusSeconds(1801);assertThatThrownBy(()->service.confirmar(usuario,s.id,new Confirmacao(true,entrada))).isInstanceOf(RegraNegocioException.class);}
 @Test void tresCorrecoesConcordantesAplicamPreferencia() throws Exception {Categoria outra=new Categoria();outra.nome="Lazer";outra.tipo=TipoLancamento.DESPESA;when(financeiro.categorias(usuario)).thenReturn(List.of(categoria,outra));List<CorrecaoCategoria> lista=new ArrayList<>();for(int i=0;i<3;i++){CorrecaoCategoria c=new CorrecaoCategoria();c.termo="almoco";c.categoriaConfirmada=outra.id;lista.add(c);}when(correcoes.findTop100ByUsuarioIdOrderByCriadaEmDesc(usuario)).thenReturn(lista);when(provedor.gerar(any(),any(),any(),anyBoolean())).thenReturn(resposta());var s=service.interpretar(usuario,"Paguei 38 no almoço");assertThat(s.campos().get("categoriaId")).isEqualTo(outra.id.toString());}
 @Test void diagnosticoUsaApenasAgregadosEValidaResposta() throws Exception {var variacao=new Variacao("Alimentação",new BigDecimal("10"),new BigDecimal("30"),new BigDecimal("20"));when(financeiro.variacoes(eq(usuario),any())).thenReturn(List.of(variacao));when(provedor.gerar(eq("DIAGNOSTICO"),any(),any(),eq(false))).thenReturn(mapper.readTree("{\"destaques\":[\"categoria_0\"],\"tendencia\":\"ALTA\"}"));var d=service.diagnosticar(usuario,YearMonth.now().toString());assertThat(d.texto()).contains("Alimentação","30,00").hasSizeLessThan(2000);assertThat(d.aviso()).contains("não constitui");var captor=org.mockito.ArgumentCaptor.forClass(Object.class);verify(provedor).gerar(eq("DIAGNOSTICO"),any(),captor.capture(),eq(false));assertThat(mapper.writeValueAsString(captor.getValue())).doesNotContain(usuario.toString(),"Alimentação","descricao");when(provedor.gerar(any(),any(),any(),anyBoolean())).thenReturn(mapper.createObjectNode());assertThatThrownBy(()->service.diagnosticar(usuario,YearMonth.now().toString())).isInstanceOf(RegraNegocioException.class);}
 @Test void diagnosticoSemDadosENoFuturo(){when(financeiro.variacoes(eq(usuario),any())).thenReturn(List.of());assertThat(service.diagnosticar(usuario,YearMonth.now().toString()).variacoes()).isEmpty();assertThatThrownBy(()->service.diagnosticar(usuario,YearMonth.now().plusMonths(1).toString())).isInstanceOf(RegraNegocioException.class);}
}
